.wsdiskret__karw{position:relative}.wsdiskret__kar{grid-auto-flow:column;grid-auto-columns:calc((100% - 44px)/3);grid-template-columns:none!important;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none}.wsdiskret__kar::-webkit-scrollbar{display:none}.wsdiskret__kar>*{scroll-snap-align:start}
.wsdiskret__pus{position:absolute;top:50%;transform:translateY(-50%);width:42px;height:42px;border-radius:50%;border:0;background:#fff;box-shadow:0 4px 14px rgba(0,0,0,.18);font-size:22px;line-height:42px;cursor:pointer;z-index:2;color:#1d2b4f;padding:0}.wsdiskret__pus--l{left:-14px}.wsdiskret__pus--d{right:-14px}
