div.wsdiskret__pog{text-align:center;border:1px solid rgba(218,100,117,.35);border-radius:16px;transition:transform .2s,box-shadow .2s}div.wsdiskret__pog:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(218,100,117,.22)}div.wsdiskret__pog>strong,div.wsdiskret__pog>span:not(.wsdiskret__pi){display:block}
